1	package registry
2	
3	import (
4		"errors"
5		"os"
6		"testing"
7		"time"
8	)
9	
10	// 本文件为撤销代转授权补充"拒绝结果保存失败"场景的回归保障，与创建授权
11	// （authorization_save_failure_test.go）及发行、转让、拆分意向的同类用例
12	// 行为对齐：非授权人请求撤销得到的 ErrForbidden、授权人撤销已使用授权得到
13	// 的 ErrAuthorizationUsed 都属于需要落盘记忆的状态类业务拒绝，登记册应保存
14	// 这两种拒绝，让同一请求重提时返回首次结果。若本次拒绝结果尚未写入原登记册
15	// 就发生写入失败，RevokeAuthorization 必须返回实际保存错误，不能只返回上述
16	// 业务错误，让调用者误以为拒绝结果已经记住。
17	//
18	// 保存失败时返回的结果必须为空：不带授权编号与状态，Replayed 为 false，
19	// 结果内的 Err 为空，单独返回的 error 保留保存失败的原因。授权内容、授权
20	// 变更记录及藏品当前持有人和版本保持操作前的状态；该操作者的本次请求号没有
21	// 被占用——即使写入失败后原登记册数据暂时无法读取，也不能让尚未保存的拒绝
22	// 留在当前已打开的登记册中，或随之后另一次正常操作被保存下来。保存条件恢复
23	// 后用同一操作者、请求号、授权编号和原因重新提交，按当时的授权情况重新
24	// 处理：拒绝条件仍存在时先成功保存此次拒绝再返回相应业务错误（首次重提不标
25	// 回放），此后完全相同的提交才回放它。失败保存的请求也不能使该操作者使用
26	// 同号撤销另一份自己有权撤销的授权时遭遇请求号冲突；只有实际保存过的结果
27	// 才继续适用原有的同号不同参数冲突规则。
28	//
29	// 必填内容缺失及授权不存在仍直接按原错误拒绝、不占用请求号，也不因当前无法
30	// 保存而变成保存错误。
31	//
32	// 失败注入方式与其他场景共用：在临时文件路径 .registry.json.tmp 上预先
33	// 建一个目录，save 在 OpenFile 阶段即以 EISDIR 失败，原快照完好可读；
34	// 另有用例同时破坏数据文件，覆盖"原数据暂时无法读取"的情形。
35	
36	// revokeAuthzSaveReq 构造一条撤销授权请求。
37	func revokeAuthzSaveReq(op, authID, rid string) RevokeAuthorizationRequest {
38		return RevokeAuthorizationRequest{Operator: op, Reason: "撤销授权", RequestID: rid, AuthID: authID}
39	}
40	
41	// setupUsedAuthzWorld 建立两份授权：a1 仍有效、未使用；a2 已由受托人 bob
42	// 代转给 carol（已使用）。代转后藏品 i1 在 carol 手中、版本 2；授权变更
43	// 记录依次为 create a1（序号 1）、create a2（序号 2）、use a2（序号 3）。
44	// a1 虽因藏品易手无法再用于代转，但尚未使用，授权人 alice 仍可撤销。
45	func setupUsedAuthzWorld(t *testing.T, r *Registry) {
46		t.Helper()
47		authzWorld(t, r)
48		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
49			t.Fatal(err)
50		}
51		if _, err := r.CreateAuthorization(createAuthReq(r, "a2", time.Hour)); err != nil {
52			t.Fatal(err)
53		}
54		if _, err := r.ProxyTransfer(proxyReq("bob", "a2", "p-a2")); err != nil {
55			t.Fatal(err)
56		}
57	}
58	
59	// assertRevokeAuthzSaveFailureEmpty 核对撤销"拒绝结果保存失败"的返回：
60	// error 是保存错误而非任何业务拒绝（含授权类的已使用、已撤销、已过期
61	// 哨兵）；结果为空——不携带授权编号或状态，业务错误为空，也不标记为重复
62	// 返回。
63	func assertRevokeAuthzSaveFailureEmpty(t *testing.T, res RevokeAuthorizationResult, err error) {
64		t.Helper()
65		assertSaveFailureError(t, err)
66		for _, s := range []error{ErrAuthorizationUsed, ErrAuthorizationRevoked, ErrAuthorizationExpired} {
67			if errors.Is(err, s) {
68				t.Fatalf("返回的应是保存错误，不能是业务拒绝 %v: %v", s, err)
69			}
70		}
71		if res.AuthID != "" || res.Status != "" || res.Replayed || res.Err != nil {
72			t.Fatalf("拒绝结果保存失败必须返回空结果: %+v", res)
73		}
74	}
75	
76	// assertRevokeRequestFree 核对请求号未被这次未保存的拒绝占用（在同一个已
77	// 打开的登记册上检查）。
78	func assertRevokeRequestFree(t *testing.T, r *Registry, req RevokeAuthorizationRequest) {
79		t.Helper()
80		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
81			t.Fatalf("未保存的拒绝不应占用请求号 %s", req.RequestID)
82		}
83	}
84	
85	// assertRevokeRequestSaved 核对拒绝结果已登记落盘。
86	func assertRevokeRequestSaved(t *testing.T, r *Registry, req RevokeAuthorizationRequest) {
87		t.Helper()
88		prev, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]
89		if !ok {
90			t.Fatalf("拒绝保存成功后应登记请求结果，请求号 %s 却空闲", req.RequestID)
91		}
92		if !prev.Rejected || prev.AuthID != req.AuthID {
93			t.Fatalf("登记的请求结果异常: %+v", prev)
94		}
95	}
