237	// TestRevokeAuthzRejectSaveFailureUnreadableDisk 覆盖：拒绝结果保存失败且
238	// 原数据暂时无法读取（commit 无法按磁盘重建状态）时，未保存的拒绝也不能
239	// 留在当前已打开的登记册中；恢复正常读写后其他操作成功保存不带入这次拒绝，
240	// 原请求重提才首次保存对应业务拒绝，再次提交才回放。无权与已使用两种拒绝
241	// 分别覆盖。
242	func TestRevokeAuthzRejectSaveFailureUnreadableDisk(t *testing.T) {
243		t.Run("forbidden", func(t *testing.T) {
244			r := mustCreate(t, tempDir(t))
245			authzWorld(t, r)
246			if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
247				t.Fatal(err)
248			}
249			req := revokeAuthzSaveReq("bob", "a1", "rv-bob")
250	
251			orig, err := os.ReadFile(dataFile(r.dir))
252			if err != nil {
253				t.Fatal(err)
254			}
255			blockBatchSave(t, r)
256			if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
257				t.Fatal(err)
258			}
259	
260			res, err := r.RevokeAuthorization(req)
261			assertRevokeAuthzSaveFailureEmpty(t, res, err)
262			// 状态未能重建时也必须显式撤销：请求号空闲，授权仍有效，历史只有
263			// 创建记录。
264			assertRevokeRequestFree(t, r, req)
265			a, _ := r.GetAuthorization("a1")
266			if a.Status != AuthActive {
267				t.Fatalf("不可读磁盘失败后授权不应改变: %+v", a)
268			}
269			if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 {
270				t.Fatalf("不可读磁盘失败后历史应只有创建: %+v", evs)
271			}
272	
273			if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
274				t.Fatal(err)
275			}
276			restoreBatchSave(t, r)
277			if err := r.RegisterAccount("dave", "路人"); err != nil {
278				t.Fatal(err)
279			}
280			assertRevokeRequestFree(t, r, req)
281	
282			res, err = r.RevokeAuthorization(req)
283			if !errors.Is(err, ErrForbidden) || res.Replayed ||
284				!errors.Is(res.Err, ErrForbidden) {
285				t.Fatalf("恢复后重提应首次保存无权拒绝: %+v, err %v", res, err)
286			}
287			res, err = r.RevokeAuthorization(req)
288			if !errors.Is(err, ErrForbidden) || !res.Replayed {
289				t.Fatalf("再次提交应回放已保存的无权拒绝: %+v, err %v", res, err)
290			}
291		})
292	
293		t.Run("used", func(t *testing.T) {
294			r := mustCreate(t, tempDir(t))
295			setupUsedAuthzWorld(t, r)
296			req := revokeAuthzSaveReq("alice", "a2", "rv-used")
297	
298			orig, err := os.ReadFile(dataFile(r.dir))
299			if err != nil {
300				t.Fatal(err)
301			}
302			blockBatchSave(t, r)
303			if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
304				t.Fatal(err)
305			}
306	
307			res, err := r.RevokeAuthorization(req)
308			assertRevokeAuthzSaveFailureEmpty(t, res, err)
309			assertRevokeRequestFree(t, r, req)
310			a, _ := r.GetAuthorization("a2")
311			if a.Status != AuthUsed || a.UsedTxSeq != 2 {
312				t.Fatalf("不可读磁盘失败后已使用授权不应改变: %+v", a)
313			}
314			if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 3 {
315				t.Fatalf("不可读磁盘失败后授权变更记录应保持 3 条: %+v", evs)
316			}
317	
318			if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
319				t.Fatal(err)
320			}
321			restoreBatchSave(t, r)
322			if err := r.RegisterAccount("dave", "路人"); err != nil {
323				t.Fatal(err)
324			}
325			assertRevokeRequestFree(t, r, req)
326	
327			res, err = r.RevokeAuthorization(req)
328			if !errors.Is(err, ErrAuthorizationUsed) || res.Replayed ||
329				!errors.Is(res.Err, ErrAuthorizationUsed) {
330				t.Fatalf("恢复后重提应首次保存已使用拒绝: %+v, err %v", res, err)
331			}
332			res, err = r.RevokeAuthorization(req)
333			if !errors.Is(err, ErrAuthorizationUsed) || !res.Replayed {
334				t.Fatalf("再次提交应回放已保存的已使用拒绝: %+v, err %v", res, err)
335			}
336		})
337	}
