237	// 已登记且可用；后续只有该账户能发行该系列的藏品或封存该系列。
238	func (r *Registry) CreateSeries(id, creatorID, metadata string) error {
239		r.mu.Lock()
240		defer r.mu.Unlock()
241		if err := r.checkOpen(); err != nil {
242			return err
243		}
244		if strings.TrimSpace(id) == "" {
245			return fmt.Errorf("%w: 系列编号不能为空", ErrInvalidArgument)
246		}
