483			missing = append(missing, "to_id")
484		}
485		if req.ExpectedVer <= 0 {
486			missing = append(missing, "expected_version")
487		}
488		if len(missing) > 0 {
489			return fmt.Errorf("%w: 转让请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
490		}
