1280	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1281	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1282	// 到期但尚未终结的授权返回 AuthExpired。
1283	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1284		r.mu.Lock()
1285		defer r.mu.Unlock()
1286		if err := r.checkOpen(); err != nil {
1287			return Authorization{}, err
1288		}
1289		a, ok := r.state.Authzs[authID]
1290		if !ok {
1291			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1292		}
1293		return Authorization{
1294			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1295			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1296			Status:    authzCurrentStatus(a, r.now()),
1297			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1298			RevokedAt: a.RevokedAt,
1299		}, nil
1300	}
1301	
1302	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1303	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1304	// 不存在时返回包裹 ErrNotFound 的错误。
1305	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1306		r.mu.Lock()
1307		defer r.mu.Unlock()
1308		if err := r.checkOpen(); err != nil {
1309			return nil, err
1310		}
1311		if _, ok := r.state.Items[itemID]; !ok {
1312			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1313		}
1314		out := make([]AuthorizationEvent, 0)
1315		for _, e := range r.state.AuthEvents {
1316			if e.ItemID != itemID {
1317				continue
1318			}
1319			out = append(out, AuthorizationEvent{
1320				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1321				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1322				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1323				OccurredAt: e.OccurredAt,
1324			})
1325		}
1326		return out, nil
1327	}
1328	
1329	// ---- 查询 ----
1330	
1331	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1332	func (r *Registry) GetItem(id string) (Item, error) {
1333		r.mu.Lock()
1334		defer r.mu.Unlock()
1335		if err := r.checkOpen(); err != nil {
1336			return Item{}, err
1337		}
1338		it, ok := r.state.Items[id]
1339		if !ok {
1340			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1341		}
1342		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1343			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1344	}
1345	
1346	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1347	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1348		r.mu.Lock()
1349		defer r.mu.Unlock()
1350		if err := r.checkOpen(); err != nil {
1351			return Holding{}, err
1352		}
1353		h, ok := r.state.Holdings[itemID]
1354		if !ok {
1355			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1356		}
1357		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1358	}
1359	
1360	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1361	// ErrNotFound 的错误；停用账户仍可正常查询。
1362	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1363		r.mu.Lock()
1364		defer r.mu.Unlock()
1365		if err := r.checkOpen(); err != nil {
1366			return nil, err
1367		}
1368		if _, ok := r.state.Accounts[accountID]; !ok {
1369			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1370		}
1371		out := make([]Holding, 0)
1372		for _, h := range r.state.Holdings {
1373			if h.OwnerID == accountID {
1374				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1375			}
1376		}
1377		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1378		return out, nil
1379	}
1380	
1381	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1382	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1383	// 返回包裹 ErrNotFound 的错误。
1384	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1385		r.mu.Lock()
1386		defer r.mu.Unlock()
1387		if err := r.checkOpen(); err != nil {
1388			return nil, err
1389		}
1390		if _, ok := r.state.Items[itemID]; !ok {
1391			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1392		}
1393		out := make([]HistoryEntry, 0)
1394		for _, e := range r.state.History {
1395			if e.ItemID != itemID {
1396				continue
1397			}
1398			out = append(out, HistoryEntry{
1399				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1400				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1401				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1402			})
1403		}
1404		return out, nil
1405	}
1406	
1407	// ---- 幂等辅助 ----
1408	
1409	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1410	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1411	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1412	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1413	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1414	func requestKey(operator, requestID string) string {
1415		b, _ := json.Marshal([2]string{operator, requestID})
1416		return string(b)
1417	}
1418	
1419	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1420	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1421	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1422	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1423	// 并回放。
1424	func isValidationErr(err error) bool {
1425		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1426	}
1427	
1428	var errCodes = map[error]string{
1429		ErrNotFound:             "not_found",
1430		ErrAlreadyExists:        "already_exists",
1431		ErrAccountInactive:      "account_inactive",
1432		ErrSeriesSealed:         "series_sealed",
1433		ErrConflict:             "conflict",
1434		ErrSameAccount:          "same_account",
1435		ErrForbidden:            "forbidden",
1436		ErrAuthorizationRevoked: "authorization_revoked",
1437		ErrAuthorizationExpired: "authorization_expired",
1438		ErrAuthorizationUsed:    "authorization_used",
1439		ErrRoyaltyFrozen:        "royalty_frozen",
1440		ErrSplitIntentRejected:  "split_intent_rejected",
1441		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1442		ErrSplitIntentInvalid:   "split_intent_invalid",
1443		ErrSplitIntentExpired:   "split_intent_expired",
1444		ErrSplitAnswered:        "split_answered",
1445	}
1446	
1447	var codeErrs = map[string]error{
1448		"not_found":              ErrNotFound,
1449		"already_exists":         ErrAlreadyExists,
1450		"account_inactive":       ErrAccountInactive,
1451		"series_sealed":          ErrSeriesSealed,
1452		"conflict":               ErrConflict,
1453		"same_account":           ErrSameAccount,
1454		"forbidden":              ErrForbidden,
1455		"authorization_revoked":  ErrAuthorizationRevoked,
1456		"authorization_expired":  ErrAuthorizationExpired,
1457		"authorization_used":     ErrAuthorizationUsed,
1458		"royalty_frozen":         ErrRoyaltyFrozen,
1459		"split_intent_rejected":  ErrSplitIntentRejected,
1460		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1461		"split_intent_invalid":   ErrSplitIntentInvalid,
1462		"split_intent_expired":   ErrSplitIntentExpired,
1463		"split_answered":         ErrSplitAnswered,
1464	}
1465	
1466	func errCode(err error) string {
1467		for sentinel, code := range errCodes {
1468			if errors.Is(err, sentinel) {
1469				return code
1470			}
1471		}
1472		return "rejected"
1473	}
1474	
1475	func codeErr(code string) error {
1476		if e, ok := codeErrs[code]; ok {
1477			return e
1478		}
1479		return errors.New("registry: 请求曾被拒绝")
1480	}
1481

