572	// 不存在（授权不存在、受托人未登记）的请求直接按原错误拒绝、不占用请求号、
573	// 不要求保存，即使数据位置暂时不可写也仍返回原参数/引用错误，不能改报保存
574	// 错误。
575	func TestProxyTransferValidationIgnoresSaveFailure(t *testing.T) {
576		r := mustCreate(t, tempDir(t))
577		authzWorld(t, r)
578		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
579			t.Fatal(err)
580		}
581	
582		blockBatchSave(t, r)
583		defer restoreBatchSave(t, r)
584	
585		// 必填内容缺失：返回 ErrInvalidArgument，不是保存错误。
586		if _, err := r.ProxyTransfer(ProxyTransferRequest{}); !errors.Is(err, ErrInvalidArgument) {
587			t.Fatalf("必填缺失应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
588		}
589		missing := proxyReq("bob", "a1", "p-miss")
590		missing.AuthID = ""
591		if _, err := r.ProxyTransfer(missing); !errors.Is(err, ErrInvalidArgument) {
592			t.Fatalf("必填缺失应返回 ErrInvalidArgument: %v", err)
593		}
594	
595		// 授权不存在：返回 ErrNotFound（结果带授权编号与业务错误），不是保存
596		// 错误，也不占用请求号。
597		notFoundReq := proxyReq("bob", "ghost", "p-nf")
598		res, err := r.ProxyTransfer(notFoundReq)
599		if !errors.Is(err, ErrNotFound) {
600			t.Fatalf("授权不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
601		}
602		if res.AuthID != "ghost" || !errors.Is(res.Err, ErrNotFound) || res.Replayed {
603			t.Fatalf("授权不存在的结果异常: %+v", res)
604		}
605		assertProxyRequestFree(t, r, notFoundReq)
606	
607		// 受托人未登记：同样是引用不存在，返回 ErrNotFound 且不占用请求号。
608		noOperatorReq := proxyReq("dave", "a1", "p-nop")
609		res, err = r.ProxyTransfer(noOperatorReq)
610		if !errors.Is(err, ErrNotFound) {
611			t.Fatalf("受托人未登记应返回 ErrNotFound，不能改报保存错误: %v", err)
612		}
613		if res.AuthID != "a1" || !errors.Is(res.Err, ErrNotFound) || res.Replayed {
614			t.Fatalf("受托人未登记的结果异常: %+v", res)
615		}
616		assertProxyRequestFree(t, r, noOperatorReq)
617	
618		// 保存条件恢复后，同一受托人用同一请求号对真实授权发起代转应正常成功：
619		// 引用不存在没有占用请求号。
620		restoreBatchSave(t, r)
621		sameIDRealAuth := proxyReq("bob", "a1", "p-nf")
622		res, err = r.ProxyTransfer(sameIDRealAuth)
623		if err != nil || res.Replayed || res.Err != nil || res.AuthID != "a1" ||
624			res.ToID != "carol" || res.Version != 2 {
625			t.Fatalf("引用不存在不应占用请求号，同号代转真实授权应成功: %+v, err %v", res, err)
626		}
627	}
628	
629	// TestProxyTransferSavedRejectionReplaysAndConflicts 覆盖保存成功后的既有
630	// 幂等语义不变：到期拒绝保存后，完全相同的请求回放首次拒绝（即使授权随后
631	// 被撤销也仍回放到期，而非改判已撤销），改动原因则按请求号冲突拒绝。
632	func TestProxyTransferSavedRejectionReplaysAndConflicts(t *testing.T) {
633		r := mustCreate(t, tempDir(t))
634		authzWorld(t, r)
635		createReq := createAuthReq(r, "a1", time.Minute)
636		if _, err := r.CreateAuthorization(createReq); err != nil {
637			t.Fatal(err)
638		}
639		r.now = func() time.Time { return createReq.ExpiresAt.Add(time.Second) }
640		req := proxyReq("bob", "a1", "late")
641	
642		// 首次：到期拒绝并成功保存。
643		res, err := r.ProxyTransfer(req)
644		if !errors.Is(err, ErrAuthorizationExpired) || res.Replayed ||
645			res.AuthID != "a1" || !errors.Is(res.Err, ErrAuthorizationExpired) {
646			t.Fatalf("首次代转应返回未回放的到期拒绝: %+v, err %v", res, err)
647		}
648		assertProxyRequestSavedRejected(t, r, req, ErrAuthorizationExpired)
649	
650		// 完全相同的请求重提：回放首次到期拒绝。
651		res, err = r.ProxyTransfer(req)
652		if !errors.Is(err, ErrAuthorizationExpired) || !res.Replayed ||
653			!errors.Is(res.Err, ErrAuthorizationExpired) {
654			t.Fatalf("相同请求应回放首次到期拒绝: %+v, err %v", res, err)
655		}
656	
657		// 改动该请求的业务内容（原因）：请求号冲突。
658		changed := req
659		changed.Reason = "换个原因"
660		if _, err := r.ProxyTransfer(changed); !errors.Is(err, ErrRequestConflict) {
661			t.Fatalf("改动业务内容应返回 ErrRequestConflict: %v", err)
662		}
663	
664		// 授权随后被撤销：原请求仍回放保存过的到期拒绝，而不是改判已撤销。
665		r.now = func() time.Time { return createReq.ExpiresAt.Add(2 * time.Second) }
666		if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{
667			Operator: "alice", Reason: "撤销", RequestID: "rv", AuthID: "a1",
668		}); err != nil {
669			t.Fatal(err)
670		}
671		res, err = r.ProxyTransfer(req)
672		if !errors.Is(err, ErrAuthorizationExpired) || !res.Replayed {
673			t.Fatalf("授权撤销后原请求仍应回放到期拒绝: %+v, err %v", res, err)
674		}
675	}
676

