package registry

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"testing"
)

func tempDir(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	return filepath.Join(dir, "data")
}

func mustCreate(t *testing.T, dir string) *Registry {
	t.Helper()
	r, err := Create(dir)
	if err != nil {
